import { DainikSamacharDashboardPage } from "@/components/landing/DainikSamacharDashboardPage";
import { auth } from "@clerk/nextjs/server";
import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "Your desk — Dainik Samachar",
  description: "Pick up a story, or ask a question.",
};

/** Signed-in home (moved from `/`, which is now the public landing). */
export default async function HomePage() {
  await auth.protect();
  return <DainikSamacharDashboardPage />;
}

import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "Dainik Samachar — Know it first",
  description:
    "AI-ranked news for India, the world and your city, plus stock, ETF and mutual fund research.",
};

// Placeholder until the scroll-tied hero lands.
export default function LandingPage() {
  return <main />;
}

import type { ReactNode } from "react";

/**
 * Public landing (`/`). The root layout's fixed-height shell is released while
 * `[data-landing-root]` is in the DOM (see `globals.css`), so the window scrolls
 * here instead of an inner container. A separate root layout would force a full
 * page load on every navigation between `/` and the app.
 */
export default function MarketingLayout({ children }: { children: ReactNode }) {
  return <div data-landing-root>{children}</div>;
}

