const { chromium } = require("/home/arnab-smnta/.nvm/versions/node/v24.10.0/lib/node_modules/@playwright/cli/node_modules/playwright");
const path = require("path");

const BASE = "http://localhost:3100";
const OUT = path.join(__dirname, "shots");
const channel = process.env.CHANNEL || undefined; // "chrome" for H.264

function collect(page, label, logs) {
  page.on("console", (m) => {
    const t = m.type();
    if (["error", "warning", "warn"].includes(t) || m.text().includes("[landing]"))
      logs.push(`[${label}] ${t}: ${m.text().slice(0, 300)}`);
  });
  page.on("pageerror", (e) => logs.push(`[${label}] pageerror: ${e.message}`));
}

async function state(page) {
  return page.evaluate(() => {
    const secs = [...document.querySelectorAll("[data-landing] section")];
    const nav = document.querySelector('nav[aria-label="Main"]');
    const canvas = document.querySelector("[data-landing] canvas");
    const video = document.querySelector("[data-landing] video");
    return {
      scrollY: Math.round(window.scrollY),
      opac: secs.map((s) => Number(getComputedStyle(s).opacity).toFixed(2)),
      inert: secs.map((s) => s.inert),
      navColor: nav && getComputedStyle(nav).color,
      canvasOpacity: canvas && getComputedStyle(canvas).opacity,
      videoTime: video && Number(video.currentTime.toFixed(2)),
      counts: window.__landingScrub,
      h1Font: getComputedStyle(document.querySelector("h1")).fontFamily,
    };
  });
}

async function scrollToP(page, p) {
  await page.evaluate((p) => {
    const span = document.querySelector("[data-landing] > div").offsetHeight - innerHeight;
    window.scrollTo({ top: p * span, behavior: "instant" });
  }, p);
  await page.waitForTimeout(2500);
}

