  const logs = [];
  const report = {};

  for (const [name, vp] of [["desktop", { width: 1440, height: 900 }], ["mobile", { width: 390, height: 844 }]]) {
    const ctx = await browser.newContext({ viewport: vp });
    const page = await ctx.newPage();
    collect(page, name, logs);
    await page.goto(BASE + "/", { waitUntil: "load" });
    const live = await page
      .waitForFunction(() => getComputedStyle(document.querySelector("[data-landing] canvas")).opacity === "1", null, { timeout: 45000 })
      .then(() => true, () => false);
    report[name] = { canvasLive: live };
    for (const p of [0, 0.45, 0.85]) {
      await scrollToP(page, p);
      report[name][p] = await state(page);
      await page.screenshot({ path: `${OUT}/${channel || "chromium"}-${name}-p${p}.png` });
    }
    if (name === "mobile") {
      await scrollToP(page, 0);
      await page.click('button[aria-label="Open menu"]');
      await page.waitForTimeout(900);
      report.menu = await page.evaluate(() => ({
        bodyOverflow: document.body.style.overflow,
        focused: document.activeElement?.getAttribute("aria-label"),
        footer: [...document.querySelectorAll("#landing-mobile-menu > div > div:last-child a")].map((a) => a.getAttribute("href")),
      }));
      await page.screenshot({ path: `${OUT}/${channel || "chromium"}-mobile-menu.png` });
      await page.keyboard.press("Escape");
      await page.waitForTimeout(700);
      report.menuAfterEsc = await page.evaluate(() => ({
        bodyOverflow: document.body.style.overflow,
        focused: document.activeElement?.getAttribute("aria-label"),
      }));
    }
    if (name === "desktop") {
      report.links = await page.evaluate(() => ({
        nav: [...document.querySelectorAll('nav[aria-label="Main"] > ul a')].map((a) => `${a.textContent}->${a.getAttribute("href")}`),
        right: [...document.querySelectorAll('nav[aria-label="Main"] > div a')].map((a) => `${a.textContent}->${a.getAttribute("href")}`),
        s1: document.querySelector('a[aria-label="Go to today\'s news"]')?.getAttribute("href"),
        cta: [...document.querySelectorAll("[data-landing] section a")].map((a) => a.getAttribute("href")),
        h1s: document.querySelectorAll("h1").length,
        header: !!document.querySelector("header"),
        footer: !!document.querySelector("footer"),
      }));
      // Next button → Section 3, then back to top.
      await scrollToP(page, 0.45);
      await page.click('button[aria-label="Next"]');
      await page.waitForTimeout(2500);
      report.afterNext = await state(page);
      await scrollToP(page, 0.45);
      await page.click('button[aria-label="Back to top"]');
      await page.waitForTimeout(2500);
      report.afterTop = (await state(page)).scrollY;

      // / → /newsStory → back, ×3 (client-side)
      await scrollToP(page, 0);
      for (let i = 0; i < 3; i++) {
        await page.click('nav[aria-label="Main"] a[href="/newsStory"]');
        await page.waitForURL("**/newsStory");
        await page.waitForTimeout(1500);
        if (i === 0)
          report.newsStoryPage = await page.evaluate(() => ({
            header: !!document.querySelector("header"),
            footer: !!document.querySelector("footer"),
            bodyOverflow: getComputedStyle(document.body).overflowY,
            counts: window.__landingScrub,
          }));
        await page.goBack();
        await page.waitForURL(BASE + "/");
        await page.waitForTimeout(2500);
      }
      report.afterNav = await state(page);
    }
    await ctx.close();
  }

  // Reduced motion
  {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: "reduce" });
    const page = await ctx.newPage();
    collect(page, "reduced", logs);
    await page.goto(BASE + "/", { waitUntil: "load" });
    await page.waitForTimeout(4000);
    await scrollToP(page, 0.5);
    report.reduced = await state(page);
    report.reduced.navLinkTransition = await page.evaluate(() => document.querySelector('nav[aria-label="Main"] li').style.transition);
    await page.screenshot({ path: `${OUT}/${channel || "chromium"}-reduced-p0.5.png` });
    await ctx.close();
  }

  // Other pages keep header/footer
  {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    collect(page, "other", logs);
    report.otherPages = {};
    for (const route of ["/about", "/pricing", "/newsStory", "/home"]) {
      await page.goto(BASE + route, { waitUntil: "load" });
      await page.waitForTimeout(800);
      report.otherPages[route] = await page.evaluate(() => ({
        url: location.pathname,
        header: !!document.querySelector("header"),
        footer: !!document.querySelector("footer"),
        bodyOverflow: getComputedStyle(document.body).overflowY,
      }));
    }
    await ctx.close();
  }

  await browser.close();
  console.log(JSON.stringify(report, null, 1));
  console.log("---- console ----");
  console.log([...new Set(logs)].join("\n"));
})();

