// Usage: LABEL=old|new BASE=http://localhost:3200 node perf.cjs
const { chromium } = require("/home/arnab-smnta/.nvm/versions/node/v24.10.0/lib/node_modules/@playwright/cli/node_modules/playwright");
const path = require("path");
const BASE = process.env.BASE || "http://localhost:3200";
const LABEL = process.env.LABEL || "run";
const OUT = path.join(__dirname, "perf");
require("fs").mkdirSync(OUT, { recursive: true });

const FAST_4G = { offline: false, latency: 165, downloadThroughput: (9e6 / 8) * 0.9, uploadThroughput: (1.5e6 / 8) * 0.9 };

const INIT = () => {
  window.__perf = { marks: {}, longtasks: [], seeked: 0 };
  new PerformanceObserver((l) => l.getEntries().forEach((e) => __perf.longtasks.push([e.startTime, e.duration]))).observe({ type: "longtask", buffered: true });
  const tick = () => {
    const m = __perf.marks;
    const now = performance.now();
    const v = document.querySelector("[data-landing] video");
    if (v && !v.__hooked) { v.__hooked = true; v.addEventListener("seeked", () => __perf.seeked++); }
    if (v && v.readyState >= 2 && !m.videoFirstFrame) m.videoFirstFrame = now;
    const c = document.querySelector("[data-landing] canvas");
    if (c && c.className.includes("opacity-100") && !m.canvasLive) m.canvasLive = now;
    const img = document.querySelector("[data-landing] img");
    if (img && img.complete && img.naturalWidth && !m.poster) m.poster = now;
    for (const n of ["landing:frame0", "landing:coarse", "landing:all"]) {
      const e = performance.getEntriesByName(n)[0];
      if (e && !m[n]) m[n] = e.startTime;
    }
    if (__perf.rec) {
      __perf.rec.raf.push(now);
      const f = c && c.dataset.frame;
      if (f !== __perf.rec.lastFrame) { __perf.rec.frameChanges++; __perf.rec.lastFrame = f; }
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
};

async function run(vpName, viewport) {
  const browser = await chromium.launch({ channel: "chrome" });
  const ctx = await browser.newContext({ viewport, deviceScaleFactor: vpName === "mobile" ? 3 : 1, isMobile: vpName === "mobile", hasTouch: vpName === "mobile" });
  const page = await ctx.newPage();
  await page.addInitScript(INIT);
  const cdp = await ctx.newCDPSession(page);
  await cdp.send("Network.enable");
  await cdp.send("Network.setCacheDisabled", { cacheDisabled: true });
  await cdp.send("Network.emulateNetworkConditions", FAST_4G);
  await cdp.send("Emulation.setCPUThrottlingRate", { rate: 4 });

  const bytes = {};
  const urls = {};
  const fromCache = { n: 0, network: 0 };
  cdp.on("Network.responseReceived", (e) => {
    urls[e.requestId] = e.response.url;
    if (e.response.fromDiskCache || e.response.fromMemoryCache) fromCache.n++;
  });
  cdp.on("Network.loadingFinished", (e) => {
    const u = urls[e.requestId] || "";
    const k = /\/landing\/frames\//.test(u) ? "frames" : /\.mp4/.test(u) ? "video" : /onlinewebfonts/.test(u) ? "font" : "other";
    bytes[k] = (bytes[k] || 0) + e.encodedDataLength;
    fromCache.network += e.encodedDataLength;
  });

  const t0 = Date.now();
  await page.goto(BASE + "/", { waitUntil: "load", timeout: 120000 });
  const loadMs = Date.now() - t0;
  await page.waitForTimeout(1000);

  // First full scroll, ~6s, while assets are still arriving.
  await browser.startTracing(page, { path: `${OUT}/${LABEL}-${vpName}-first-scroll.json`, screenshots: false });
  await page.evaluate(() => { __perf.rec = { raf: [], frameChanges: 0, lastFrame: undefined, seeked0: __perf.seeked, start: performance.now() }; });
  const span = await page.evaluate(() => document.querySelector("[data-landing] > div").offsetHeight - innerHeight);
  const steps = 60;
  for (let i = 0; i < steps; i++) {
    if (vpName === "mobile") await page.evaluate((y) => scrollBy(0, y), span / steps);
    else await page.mouse.wheel(0, span / steps);
    await page.waitForTimeout(100);
  }
  await page.waitForTimeout(800);
  const scroll = await page.evaluate(() => {
    const r = __perf.rec; __perf.rec = null;
    const iv = r.raf.slice(1).map((t, i) => t - r.raf[i]);
    const dur = (r.raf.at(-1) - r.raf[0]) / 1000;
    const lt = __perf.longtasks.filter(([s]) => s >= r.start);
    iv.sort((a, b) => a - b);
    return {
      seconds: +dur.toFixed(2),
      rafFps: +(iv.length / dur).toFixed(1),
      p95FrameMs: +iv[Math.floor(iv.length * 0.95)].toFixed(1),
      framesOver50ms: iv.filter((x) => x > 50).length,
      visualUpdatesPerSec: +((r.frameChanges + (__perf.seeked - r.seeked0)) / dur).toFixed(1),
      longTasks: lt.length,
      longTaskMs: Math.round(lt.reduce((a, [, d]) => a + d, 0)),
      endedAtBottom: Math.abs(scrollY - (document.querySelector("[data-landing] > div").offsetHeight - innerHeight)) < 5,
    };
  });
  await browser.stopTracing();

  // Wait for everything to finish loading (up to 90s), then read milestones.
  await page.waitForFunction(() => __perf.marks["landing:all"] || __perf.marks.canvasLive, null, { timeout: 90000, polling: 500 }).catch(() => {});
  await page.waitForTimeout(1500);
  const marks = await page.evaluate(() => Object.fromEntries(Object.entries(__perf.marks).map(([k, v]) => [k, Math.round(v)])));
  const totalBytes = Object.values(bytes).reduce((a, b) => a + b, 0);

  // Second visit with cache on.
  await cdp.send("Network.setCacheDisabled", { cacheDisabled: false });
  await page.evaluate(() => scrollTo(0, 0));
  fromCache.n = 0; fromCache.network = 0;
  for (const k of Object.keys(bytes)) delete bytes[k];
  await page.goto(BASE + "/", { waitUntil: "load" });
  await page.waitForFunction(() => __perf.marks["landing:all"] || __perf.marks.canvasLive, null, { timeout: 90000, polling: 500 }).catch(() => {});
  await page.waitForTimeout(1500);
  const second = { networkBytes: fromCache.network, byKind: { ...bytes }, responsesFromCache: fromCache.n, marks: await page.evaluate(() => Object.fromEntries(Object.entries(__perf.marks).map(([k, v]) => [k, Math.round(v)]))) };
  await browser.close();
  return { loadMs, marks, scroll, bytes: { ...Object.fromEntries(Object.entries(bytes)), total: totalBytes }, firstBytesByKind: undefined, second };
}

(async () => {
  const res = {};
  for (const [n, vp] of [["desktop", { width: 1440, height: 900 }], ["mobile", { width: 390, height: 844 }]]) {
    try { res[n] = await run(n, vp); } catch (e) { res[n] = { error: e.message }; }
  }
  require("fs").writeFileSync(`${OUT}/${LABEL}.json`, JSON.stringify(res, null, 1));
  console.log(JSON.stringify(res, null, 1));
})();

